import{_ as c,r as e,o as i,c as u,e as p,a as n,s as t,d as s}from"./chunks/framework.CXcwiNg-.js";const x=JSON.parse('{"title":"Компоненты - October CMS - 3.x","titleTemplate":false,"description":"Настраиваемые контроллеры, которые можно подключить к любой странице, фрагменту или макету.","frontmatter":{"subtitle":"Настраиваемые контроллеры, которые можно подключить к любой странице, фрагменту или макету."},"headers":[{"level":2,"title":"Введение","slug":"введение","link":"#введение","children":[]},{"level":2,"title":"Псевдонимы компонентов","slug":"псевдонимы-компонентов","link":"#псевдонимы-компонентов","children":[]},{"level":2,"title":"Использование внешних значений свойств","slug":"использование-внешних-значении-своиств","link":"#использование-внешних-значении-своиств","children":[]},{"level":2,"title":"Передача переменных в компоненты","slug":"передача-переменных-в-компоненты","link":"#передача-переменных-в-компоненты","children":[]},{"level":2,"title":"Настройка разметки по умолчанию","slug":"настроика-разметки-по-умолчанию","link":"#настроика-разметки-по-умолчанию","children":[{"level":3,"title":"Перенос разметки по умолчанию во фрагмент","slug":"перенос-разметки-по-умолчанию-во-фрагмент","link":"#перенос-разметки-по-умолчанию-во-фрагмент","children":[]},{"level":3,"title":"Переопределение фрагментов компонента","slug":"переопределение-фрагментов-компонента","link":"#переопределение-фрагментов-компонента","children":[]}]},{"level":2,"title":"Компонент \\"View Bag\\"","slug":"компонент-view-bag","link":"#компонент-view-bag","children":[{"level":3,"title":"AJAX-обработчики и фрагменты","slug":"ajax-обработчики-и-фрагменты","link":"#ajax-обработчики-и-фрагменты","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}]}],"relativePath":"3.x/ru/cms/themes/components.md","filePath":"3.x/ru/cms/themes/components.md"}'),r={name:"3.x/ru/cms/themes/components.md"};function g(k,a,d,m,v,h){const o=e("pre-heading"),l=e("post-heading");return i(),u("div",null,[p(o),a[0]||(a[0]=n("h1",null,"Компоненты",-1)),p(l),a[1]||(a[1]=t(`<p>Компоненты — это ключевая возможность для создания масштабируемых и современных решений с помощью October CMS. Каждый компонент реализует определённую функциональность, расширяющую ваш сайт. Компоненты могут выводить HTML-разметку на странице, но это не обязательно — другие важные возможности компонентов включают <a href="./../ajax/introduction.html">обработку AJAX-запросов</a>, обработку отправки форм и управление жизненным циклом выполнения страницы, что позволяет внедрять переменные на страницы или реализовывать безопасность сайта.</p><p>Эта статья описывает основы работы с компонентами и не объясняет, как использовать <a href="./../ajax/handlers.html">компоненты с AJAX</a>, <a href="./../../extend/cms-components.html">разрабатывать компоненты</a> как часть плагинов или <a href="./../components/section.html">компоненты, включённые</a> в October CMS.</p><h2 id="введение"><a href="#введение" class="header-anchor">#</a> Введение</h2><p>Компоненты можно найти в редакторе панели администрирования. Вы можете добавлять компоненты на страницы, во фрагменты и в макеты, нажав кнопку «Компоненты» на панели инструментов любого открытого документа. Если вы используете текстовый редактор, вы можете подключить компонент к странице или макету, добавив его имя в секцию конфигурации файла шаблона. Следующий пример демонстрирует добавление демонстрационного компонента To-Do на страницу.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Components demonstration</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/components</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- HTML Content Here --&gt;</span>
</code></pre></div></div><p>Это инициализирует компонент со свойствами, определёнными в секции компонента. Многие компоненты имеют свойства, но это не обязательное требование. Некоторые свойства являются обязательными, а некоторые имеют значения по умолчанию. Если вы не уверены, какие свойства поддерживает компонент, обратитесь к документации, предоставленной разработчиком, или используйте Инспектор в редакторе панели администрирования. Инспектор открывается при нажатии на компонент в панели компонентов страницы или макета.</p><div class="custom-block aside"><p>Если два компонента с одинаковым именем назначены странице и макету одновременно, приоритет имеет компонент страницы.</p></div><p>При обращении к компоненту автоматически создаётся переменная страницы, совпадающая с именем компонента (<code>demoTodo</code> в предыдущем примере). Компоненты, предоставляющие HTML-разметку, могут быть отрендерены на странице с помощью тега <code>{% component %}</code>, как показано ниже.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block warning"><p>Использование компонентов внутри фрагментов имеет ограниченную функциональность, это подробнее описано в разделе <a href="./partials.html">Динамические фрагменты</a> документации.</p></div><h2 id="псевдонимы-компонентов"><a href="#псевдонимы-компонентов" class="header-anchor">#</a> Псевдонимы компонентов</h2><p>Если два плагина регистрируют компоненты с одинаковым именем, вы можете подключить компонент, используя его полное имя класса и назначив ему <em>псевдоним</em>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">October\\Demo\\Components\\Todo demoTodoAlias</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><p>Первый параметр в секции — это имя класса, второй — псевдоним компонента, который будет использоваться при подключении к странице. Если вы указали псевдоним компонента, его следует использовать повсюду в коде страницы при обращении к компоненту. Обратите внимание, что следующий пример ссылается на псевдоним компонента:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodoAlias<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Псевдонимы также позволяют определять несколько компонентов одного класса на одной странице, используя сначала краткое имя, а затем псевдоним. Это позволяет использовать несколько экземпляров одного компонента на странице.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo todoA</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">10</span>
<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo todoB</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
</code></pre></div><h2 id="использование-внешних-значении-своиств"><a href="#использование-внешних-значении-своиств" class="header-anchor">#</a> Использование внешних значений свойств</h2><p>По умолчанию значения свойств инициализируются в секции конфигурации, где определён компонент, и значения свойств являются статическими, как показано ниже:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">20</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div>`,20)),a[2]||(a[2]=n("div",null,[n("p",null,[s("Однако существует способ инициализировать свойства значениями, загруженными из внешних параметров — параметров URL или параметров "),n("a",{href:"./partials.html"},"фрагмента"),s(" (для компонентов, определённых во фрагментах). Используйте синтаксис "),n("code",{"v-pre":""},"{{ paramName }}"),s(" для значений, которые должны загружаться из переменных фрагмента:")])],-1)),a[3]||(a[3]=t(`<div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>В приведённом выше примере, предполагая, что компонент <strong>demoTodo</strong> определён во фрагменте, он будет инициализирован значением, загруженным из переменной фрагмента <strong>maxItems</strong>:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>my-todo-partial<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>10<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Вы можете использовать точечную нотацию для получения глубоко вложенного значения из внешнего параметра:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ data.maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div>`,5)),a[4]||(a[4]=n("div",null,[n("p",null,[s("Для загрузки значения свойства из параметра URL используйте синтаксис "),n("code",{"v-pre":""},"{{ :paramName }}"),s(", где имя начинается с двоеточия ("),n("code",{"v-pre":""},":"),s("), например.")])],-1)),a[5]||(a[5]=t(`<div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">maxItems</span> <span class="token punctuation">=</span> <span class="token value attr-value">{{ :maxItems }}</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>Страница, к которой принадлежит компонент, должна иметь соответствующий определённый <a href="./pages.html">параметр URL</a>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/todo/:maxItems</span>&quot;</span>
</code></pre></div><p>В панели администрирования October вы можете использовать Инспектор для назначения внешних значений свойствам компонентов. В Инспекторе не нужно использовать фигурные скобки для ввода имени параметра. Каждое поле в Инспекторе имеет значок справа, который открывает редактор имени внешнего параметра. Введите имя параметра как <code>paramName</code> для переменных фрагмента или <code>:paramName</code> для параметров URL.</p><h2 id="передача-переменных-в-компоненты"><a href="#передача-переменных-в-компоненты" class="header-anchor">#</a> Передача переменных в компоненты</h2><p>Компоненты могут быть спроектированы для использования переменных во время рендеринга, аналогично <a href="./partials.html">переменным фрагментов</a>, они могут быть указаны после имени компонента в теге <code>{% component %}</code>. Указанные переменные явно переопределяют значения <a href="./../../extend/cms-components.html">свойств компонента</a>, включая внешние значения свойств.</p><p>В этом примере свойство <strong>maxItems</strong> компонента будет установлено в <em>7</em> во время рендеринга компонента:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodoAlias<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>7<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="настроика-разметки-по-умолчанию"><a href="#настроика-разметки-по-умолчанию" class="header-anchor">#</a> Настройка разметки по умолчанию</h2><div class="custom-block aside"><p>Разметка по умолчанию в компоненте является шаблонным кодом, цель которого — предоставить простой пример использования.</p></div><p>Существуют два способа настройки разметки компонента по умолчанию:</p><ul><li>скопировать разметку по умолчанию в вашу тему</li><li>переопределить фрагмент компонента по одному</li></ul><p>Переопределение фрагмента компонента имеет очень ограниченный набор применений. В большинстве случаев преобразование фрагмента компонента в CMS-фрагмент значительно проще, и разница в таком подходе минимальна.</p><p>В качестве примера рассмотрим компонент блога, рендеримый следующим образом.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blog</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>blog<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Приведённый выше код фактически эквивалентен следующему.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blog</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blog::default<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Если вы скопируете фрагмент <strong>default.htm</strong> из компонента в вашу тему как фрагмент <strong>blog-default.htm</strong>, вы сможете рендерить его тем же способом.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blog</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blog-default<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Здесь видно, что использование CMS-фрагментов для настройки содержимого — это просто, и это демонстрирует истинную мощь компонентов. Существуют лишь редкие случаи, когда тема должна переопределять фрагменты компонентов, и это подробнее описано ниже.</p><h3 id="перенос-разметки-по-умолчанию-во-фрагмент"><a href="#перенос-разметки-по-умолчанию-во-фрагмент" class="header-anchor">#</a> Перенос разметки по умолчанию во фрагмент</h3><p>Каждый компонент имеет точку входа — фрагмент <strong>default.htm</strong>, который рендерится при вызове тега <code>{% component %}</code>. В следующем примере мы предполагаем, что компонент называется <strong>blogPost</strong>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">blog/post</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPost</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&quot;</span>blogPost<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Результат будет отрендерен из каталога плагина <strong>components/blogpost/default.htm</strong>. Вы можете скопировать всю разметку из этого файла и вставить её непосредственно на страницу или в новый фрагмент, например, <strong>blog-post.htm</strong>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>post<span class="token punctuation">.</span>description <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Внутри разметки вы можете заметить ссылки на переменную <code>__SELF__</code> — она ссылается на объект компонента и должна быть заменена псевдонимом компонента, используемым на странице, в данном примере это <code>blogPost</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blogPost<span class="token punctuation">.</span>post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blogPost<span class="token punctuation">.</span>post<span class="token punctuation">.</span>description <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Это единственное изменение, необходимое для того, чтобы разметка компонента по умолчанию работала в любом месте темы. Теперь разметку компонента можно настроить и рендерить с помощью фрагмента темы.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>blog-post<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Этот процесс можно повторить для всех остальных фрагментов, находящихся в каталоге фрагментов компонента.</p><h3 id="переопределение-фрагментов-компонента"><a href="#переопределение-фрагментов-компонента" class="header-anchor">#</a> Переопределение фрагментов компонента</h3><p>Все фрагменты компонента могут быть переопределены с помощью фрагментов темы. Это полезно, когда компонент имеет строгую реализацию и предоставляет возможность настройки определённых областей своей разметки.</p><p>В качестве примера, если компонент с именем <strong>channel</strong> использует фрагмент <strong>title.htm</strong>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">mypage</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">channel</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&quot;</span>channel<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Мы можем переопределить фрагмент, создав файл в нашей теме с именем <strong>partials/channel/title.htm</strong>.</p><p>Сегменты пути файла разбиваются следующим образом:</p><div class="table"><table tabindex="0"><thead><tr><th>Segment</th><th>Description</th></tr></thead><tbody><tr><td><strong>partials</strong></td><td>каталог фрагментов темы</td></tr><tr><td><strong>channel</strong></td><td>псевдоним компонента (подкаталог фрагментов)</td></tr><tr><td><strong>title.htm</strong></td><td>фрагмент компонента для переопределения</td></tr></tbody></table></div><p>Имя подкаталога фрагмента можно изменить на любое, просто назначив компоненту псевдоним с таким же именем. Например, назначив компоненту <strong>channel</strong> другой псевдоним <strong>foobar</strong>, каталог переопределения также изменится.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">channel foobar</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&quot;</span>foobar<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Теперь мы можем переопределить фрагмент <strong>title.htm</strong>, создав файл в нашей теме с именем <strong>partials/foobar/title.htm</strong>.</p><h2 id="компонент-view-bag"><a href="#компонент-view-bag" class="header-anchor">#</a> Компонент &quot;View Bag&quot;</h2><div class="custom-block aside"><p>Компонент viewBag скрыт в панели администрирования и доступен только при файловом редактировании. Он также может использоваться другими плагинами для хранения данных.</p></div><p>В October CMS есть специальный встроенный компонент <code>viewBag</code>, который можно использовать на любой странице или в любом макете. Он позволяет определять произвольные свойства и легко обращаться к ним в области разметки как к переменным. Хороший пример использования — определение активного пункта меню внутри страницы.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">About</span>&quot;</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/about.html</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">viewBag</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">activeMenu</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">about</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Page content...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Любое свойство, определённое для компонента, становится доступным внутри разметки страницы, макета или фрагмента через переменную <code>viewBag</code>. Например, в этом макете класс <strong>active</strong> добавляется к элементу списка, если значение <code>viewBag.activeMenu</code> установлено в <strong>about</strong>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Default layout</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code>...

<span class="token comment">&lt;!-- Main navigation --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> viewBag<span class="token punctuation">.</span>activeMenu <span class="token operator">==</span> <span class="token string"><span class="token punctuation">&#39;</span>about<span class="token punctuation">&#39;</span></span> <span class="token operator">?</span> <span class="token string"><span class="token punctuation">&#39;</span>active<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>About<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    ...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h3 id="ajax-обработчики-и-фрагменты"><a href="#ajax-обработчики-и-фрагменты" class="header-anchor">#</a> AJAX-обработчики и фрагменты</h3><p>Компоненты могут вводить <a href="./../ajax/introduction.html">AJAX-обработчики</a> и <a href="./partials.html">фрагменты</a> в жизненный цикл темы, используя префикс с именем компонента и два символа <code>::</code>. Например, все AJAX-обработчики, определённые компонентами, доступны глобально.</p><div class="language-html extra-class"><pre class="language-html"><code>data-request=&quot;onMyComponentHandler&quot;
</code></pre></div><p>Однако при конфликте имён можно использовать полное имя.</p><div class="language-html extra-class"><pre class="language-html"><code>data-request=&quot;componentName::onMyComponentHandler&quot;
</code></pre></div><p>Фрагменты, рендеримые вне компонента, должны использовать своё полное имя.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>componentName::component-partial<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Подробнее о фрагментах компонентов читайте в разделе <a href="./../../extend/cms-components.html">разработка компонентов</a>.</p><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./../../extend/cms-components.html">CMS Component Development</a></li></ul></div>`,56))])}const b=c(r,[["render",g]]);export{x as __pageData,b as default};
